#include <bits/stdc++.h>
using namespace std;
static int hexval(char c) { return isdigit((unsigned char)c) ? c - '0' : (tolower(c) - 'a' + 10); }
int main() {
    string in((istreambuf_iterator<char>(cin)), istreambuf_iterator<char>());
    // Decode the JSON string into code points (a surrogate pair is one character, as in Python).
    vector<uint32_t> s;
    size_t i = in.find('"') + 1;
    while (in[i] != '"') {
        unsigned char c = in[i];
        uint32_t cp;
        if (c == '\\') {
            char e = in[i + 1];
            i += 2;
            if (e == 'u') {
                cp = hexval(in[i]) << 12 | hexval(in[i+1]) << 8 | hexval(in[i+2]) << 4 | hexval(in[i+3]);
                i += 4;
                if (cp >= 0xD800 && cp < 0xDC00 && in[i] == '\\' && in[i + 1] == 'u') {
                    uint32_t lo = hexval(in[i+2]) << 12 | hexval(in[i+3]) << 8 | hexval(in[i+4]) << 4 | hexval(in[i+5]);
                    if (lo >= 0xDC00 && lo < 0xE000) { cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00); i += 6; }
                }
            } else cp = e == 'n' ? '\n' : e == 't' ? '\t' : e == 'r' ? '\r' : e == 'b' ? '\b' : e == 'f' ? '\f' : e;
        } else if (c < 0x80) {
            cp = c; i++;
        } else {  // raw UTF-8
            int len = c >= 0xF0 ? 4 : c >= 0xE0 ? 3 : 2;
            cp = c & (0xFF >> (len + 1));
            for (int k = 1; k < len; k++) cp = cp << 6 | (in[i + k] & 0x3F);
            i += len;
        }
        s.push_back(cp);
    }
    int n = s.size();
    if (!n) { cout << 0 << "\n"; return 0; }
    vector<vector<int>> dp(n + 1, vector<int>(n, 0));  // dp[l][r]; dp[l][r] = 0 when l > r
    for (int l = n - 1; l >= 0; l--) {
        dp[l][l] = 1;
        for (int r = l + 1; r < n; r++) {
            int best = 1 + dp[l + 1][r];
            for (int k = l + 1; k <= r; k++)
                if (s[l] == s[k]) best = min(best, (k > l + 1 ? dp[l + 1][k - 1] : 0) + dp[k][r]);
            dp[l][r] = best;
        }
    }
    cout << dp[0][n - 1] << "\n";
}

import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) throws IOException {
        String in = new String(System.in.readAllBytes(), StandardCharsets.UTF_8);
        // Decode the JSON string; a surrogate pair is one character, as in Python.
        StringBuilder sb = new StringBuilder();
        int i = in.indexOf('"') + 1;
        while (in.charAt(i) != '"') {
            char c = in.charAt(i++);
            if (c != '\\') { sb.append(c); continue; }
            char e = in.charAt(i++);
            switch (e) {
                case 'u': sb.append((char) Integer.parseInt(in.substring(i, i + 4), 16)); i += 4; break;
                case 'n': sb.append('\n'); break;
                case 't': sb.append('\t'); break;
                case 'r': sb.append('\r'); break;
                case 'b': sb.append('\b'); break;
                case 'f': sb.append('\f'); break;
                default: sb.append(e);
            }
        }
        int[] s = sb.toString().codePoints().toArray();
        int n = s.length;
        if (n == 0) { System.out.println(0); return; }
        int[][] dp = new int[n + 1][n];  // dp[l][r]; 0 when l > r
        for (int l = n - 1; l >= 0; l--) {
            dp[l][l] = 1;
            for (int r = l + 1; r < n; r++) {
                int best = 1 + dp[l + 1][r];
                for (int k = l + 1; k <= r; k++)
                    if (s[l] == s[k]) best = Math.min(best, (k > l + 1 ? dp[l + 1][k - 1] : 0) + dp[k][r]);
                dp[l][r] = best;
            }
        }
        System.out.println(dp[0][n - 1]);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"unicode/utf16"
	"unicode/utf8"
)

func main() {
	data, _ := io.ReadAll(os.Stdin)
	// Decode the JSON string into UTF-16 units, then pair surrogates into
	// code points, so a character is counted the way Python counts it.
	var units []uint16
	i := 0
	for data[i] != '"' {
		i++
	}
	for i++; data[i] != '"'; {
		c := data[i]
		switch {
		case c == '\\':
			e := data[i+1]
			i += 2
			switch e {
			case 'u':
				v, _ := strconv.ParseUint(string(data[i:i+4]), 16, 16)
				units = append(units, uint16(v))
				i += 4
			case 'n':
				units = append(units, '\n')
			case 't':
				units = append(units, '\t')
			case 'r':
				units = append(units, '\r')
			case 'b':
				units = append(units, '\b')
			case 'f':
				units = append(units, '\f')
			default:
				units = append(units, uint16(e))
			}
		case c < utf8.RuneSelf:
			units = append(units, uint16(c))
			i++
		default: // raw UTF-8
			r, size := utf8.DecodeRune(data[i:])
			units = utf16.AppendRune(units, r)
			i += size
		}
	}
	var s []int
	for k := 0; k < len(units); k++ {
		u := int(units[k])
		if 0xD800 <= u && u < 0xDC00 && k+1 < len(units) && 0xDC00 <= units[k+1] && units[k+1] < 0xE000 {
			u = 0x10000 + (u-0xD800)<<10 + int(units[k+1]) - 0xDC00
			k++
		}
		s = append(s, u)
	}
	n := len(s)
	if n == 0 {
		fmt.Println(0)
		return
	}
	dp := make([][]int, n+1) // dp[l][r]; 0 when l > r
	for l := range dp {
		dp[l] = make([]int, n)
	}
	for l := n - 1; l >= 0; l-- {
		dp[l][l] = 1
		for r := l + 1; r < n; r++ {
			best := 1 + dp[l+1][r]
			for k := l + 1; k <= r; k++ {
				if s[l] == s[k] {
					middle := 0
					if k > l+1 {
						middle = dp[l+1][k-1]
					}
					best = min(best, middle+dp[k][r])
				}
			}
			dp[l][r] = best
		}
	}
	fmt.Println(dp[0][n-1])
}
